 "content": "def transform(grid):
    """Use the alternating row motif to repair short 0/1 streaks.

    Each odd row consists of five variable cells separated by fixed separators.
    The demos show the local rule: any run of 0s or 1s of length >=3 is set to
    1s for a 0-run, or 0s for a 1-run, while singleton/double runs remain.
    """
    out = [list(row) for row in grid]
    if not out:
        return out
    vals = {x for row in grid for x in row}
    if len(vals) != 2:
        return out
    bg = max(vals, key=lambda v: sum(row.count(v) for row in grid))
    ink = next(x for x in vals if x != bg)
    cols = [1, 4, 7, 10, 13]
    for r in range(1, len(out), 2):
        active = [c for c in cols if c < len(out[r])]
        bits = [int(out[r][c] == ink) for c in active]
        i = 0
        while i < len(bits):
            j = i + 1
            while j < len(bits) and bits[j] == bits[i]:
                j += 1
            if j - i >= 3:
                bits[i:j] = [1 - bits[i]] * (j - i)
            i = j
        for c, bit in zip(active, bits):
            out[r][c] = ink if bit else bg
    return out
